function useScroll() {
  const [y, setY] = useState(0);
  useEffect(() => {
    const h = () => setY(window.scrollY);
    window.addEventListener("scroll", h, { passive: true });
    return () => window.removeEventListener("scroll", h);
  }, []);
  return y;
}

function useReveal(delay = 0) {
  const ref = useRef(null);
  const [v, setV] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const o = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          setTimeout(() => setV(true), delay);
          o.disconnect();
        }
      },
      { threshold: 0.06 }
    );
    o.observe(el);
    return () => o.disconnect();
  }, [delay]);
  return { ref, v };
}

function HeroCanvas() {
  const canvasRef = useRef(null);
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let raf;
    let scrollY = 0;
    const onScroll = () => { scrollY = window.scrollY; };
    window.addEventListener("scroll", onScroll, { passive: true });

    const resize = () => {
      canvas.width = window.innerWidth * 2;
      canvas.height = window.innerHeight * 2;
      canvas.style.width = "100%";
      canvas.style.height = "100%";
    };
    resize();
    window.addEventListener("resize", resize);

    // Generate sphere particles
    const count = 4000;
    const particles = [];
    const radius = Math.min(window.innerWidth, window.innerHeight) * 0.7;
    const colors = [
      [45,212,191],[45,212,191],[45,212,191],
      [94,234,212],[94,234,212],
      [153,246,228],
      [249,115,22],
    ];

    for (let i = 0; i < count; i++) {
      // Fibonacci sphere distribution
      const y = 1 - (i / (count - 1)) * 2;
      const radAtY = Math.sqrt(1 - y * y);
      const theta = i * Math.PI * (3 - Math.sqrt(5));
      const noise = 0.93 + Math.random() * 0.14;

      particles.push({
        ox: Math.cos(theta) * radAtY * noise,
        oy: y * noise,
        oz: Math.sin(theta) * radAtY * noise,
        size: 0.8 + Math.random() * 2,
        color: colors[Math.floor(Math.random() * colors.length)],
        phase: Math.random() * Math.PI * 2,
      });
    }

    // Ring particles
    const ringCount = 600;
    for (let i = 0; i < ringCount; i++) {
      const angle = (i / ringCount) * Math.PI * 2;
      const rr = 1.12 + (Math.random() - 0.5) * 0.08;
      const tilt = (Math.random() - 0.5) * 0.06;
      particles.push({
        ox: Math.cos(angle) * rr,
        oy: tilt,
        oz: Math.sin(angle) * rr,
        size: 0.5 + Math.random() * 1.2,
        color: Math.random() < 0.9 ? [45,212,191] : [249,115,22],
        phase: Math.random() * Math.PI * 2,
        ring: true,
      });
    }

    let time = 0;
    let mouseX = 0.5, mouseY = 0.5;
    const onMouseMove = (e) => {
      mouseX = e.clientX / window.innerWidth;
      mouseY = e.clientY / window.innerHeight;
    };
    window.addEventListener("mousemove", onMouseMove);

    const draw = () => {
      time += 0.004;
      const w = canvas.width;
      const h = canvas.height;
      const cx = w / 2;
      const cy = h / 2;
      const r = radius * (w / (window.innerWidth));
      const fov = 600;
      const scrollTilt = scrollY * 0.0003;

      ctx.clearRect(0, 0, w, h);

      // Rotation angles
      const rotY = time * 0.5;
      const rotX = -0.25 + scrollTilt;
      const ringRotY = -time * 0.3;

      // Mouse position in canvas space
      const mx = mouseX * w;
      const my = mouseY * h;
      const repulseRadius = 180;

      // Sort particles by Z for proper layering
      const projected = particles.map((p) => {
        const isRing = p.ring;
        const ry = isRing ? ringRotY : rotY;
        const rx = isRing ? 0.3 : rotX;

        // Rotate Y
        let x = p.ox * Math.cos(ry) - p.oz * Math.sin(ry);
        let z = p.ox * Math.sin(ry) + p.oz * Math.cos(ry);
        let y = p.oy;

        // Rotate X
        const y2 = y * Math.cos(rx) - z * Math.sin(rx);
        const z2 = y * Math.sin(rx) + z * Math.cos(rx);
        y = y2;
        z = z2;

        const scale = fov / (fov + z * r);
        let px = cx + x * r * scale;
        let py = cy + y * r * scale;

        // Mouse repulsion
        const dx = px - mx;
        const dy = py - my;
        const dist = Math.sqrt(dx * dx + dy * dy);
        let mouseBoost = 0;
        if (dist < repulseRadius && dist > 0) {
          const force = (1 - dist / repulseRadius) * 40;
          px += (dx / dist) * force;
          py += (dy / dist) * force;
          mouseBoost = (1 - dist / repulseRadius);
        }

        const pulse = 0.6 + 0.4 * Math.sin(time * 3 + p.phase);
        const depthAlpha = Math.max(0.05, Math.min(1, (z + 1.2) * 0.6));

        return { px, py, z, size: p.size * scale * pulse, color: p.color, alpha: depthAlpha * pulse, isRing, mouseBoost };
      });

      projected.sort((a, b) => a.z - b.z);

      for (const p of projected) {
        const [cr, cg, cb] = p.color;
        const sz = p.size * 2 * (1 + p.mouseBoost * 0.6);
        const alpha = p.alpha * (p.isRing ? 0.5 : 0.8);
        const boost = p.mouseBoost;

        if (sz < 0.3 || alpha < 0.02) continue;

        // Enhanced glow near cursor
        if (boost > 0.1) {
          ctx.beginPath();
          ctx.arc(p.px, p.py, sz * 5, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(${cr},${cg},${cb},${boost * 0.08})`;
          ctx.fill();
        }

        // Glow
        ctx.beginPath();
        ctx.arc(p.px, p.py, sz * 3, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${cr},${cg},${cb},${alpha * 0.06 + boost * 0.04})`;
        ctx.fill();

        // Core
        ctx.beginPath();
        ctx.arc(p.px, p.py, sz, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${cr},${cg},${cb},${Math.min(1, alpha + boost * 0.4)})`;
        ctx.fill();
      }

      raf = requestAnimationFrame(draw);
    };
    raf = requestAnimationFrame(draw);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener("resize", resize);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("mousemove", onMouseMove);
    };
  }, []);
  return <canvas ref={canvasRef} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", pointerEvents: "none" }} />;
}

function Reveal({ children, delay = 0, style = {}, parallax = 0 }) {
  const { ref, v } = useReveal(delay);
  const [offset, setOffset] = useState(0);
  useEffect(() => {
    if (!parallax || !ref.current) return;
    const handleScroll = () => {
      const rect = ref.current.getBoundingClientRect();
      const center = rect.top + rect.height / 2;
      const viewCenter = window.innerHeight / 2;
      setOffset((center - viewCenter) * parallax * -0.1);
    };
    window.addEventListener("scroll", handleScroll, { passive: true });
    handleScroll();
    return () => window.removeEventListener("scroll", handleScroll);
  }, [parallax]);
  return (
    <div
      ref={ref}
      style={{
        opacity: v ? 1 : 0,
        transform: v ? `translateY(${offset}px)` : "translateY(28px)",
        transition: `opacity 0.85s cubic-bezier(0.16,1,0.3,1) ${delay}ms, transform 0.15s linear`,
        willChange: "transform, opacity",
        ...style,
      }}
    >
      {children}
    </div>
  );
}

function WordReveal({ text, style = {} }) {
  const ref = useRef(null);
  const [vis, setVis] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const o = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) {
          const words = text.split(" ");
          words.forEach((_, i) => setTimeout(() => setVis(i + 1), i * 120));
          o.disconnect();
        }
      },
      { threshold: 0.2 }
    );
    o.observe(el);
    return () => o.disconnect();
  }, [text]);
  const words = text.split(" ");
  return (
    <div ref={ref} style={style}>
      {words.map((w, i) => (
        <span
          key={i}
          style={{
            display: "inline-block",
            opacity: i < vis ? 1 : 0,
            transform: i < vis ? "translateY(0)" : "translateY(16px)",
            transition: `all 0.6s cubic-bezier(0.16,1,0.3,1) ${i * 0.05}s`,
            marginRight: "0.3em",
          }}
        >
          {w}
        </span>
      ))}
    </div>
  );
}

